test("x", () => {
  let n = 0;
  let p = 0;
  const s = z.object({
    a: z.string().default(() => {
      n++;
      return "d";
    }),
    b: z.string().prefault(() => {
      p++;
      return "p";
    }),
  });
  expect(s.parse({})).toEqual({ a: "d", b: "p" });
  expect([n, p]).toEqual([1, 1]);
});

